local _mockBattlePassFreeGotIds = { 1 }
local _mockBattlePassVipGotIds = {}
local _mockBag = nil

local function _copyList(list)
    local ret = {}
    for _, v in ipairs(list or {}) do
        ret[#ret + 1] = v
    end
    return ret
end

local function _contains(list, value)
    for _, v in ipairs(list or {}) do
        if v == value then return true end
    end
    return false
end

local function _getBattlePassMeta(id)
    for _, meta in ipairs(MockData._RUNTIME_CONFIG.battlePassMetas or {}) do
        if meta.id == id then return meta end
    end
end

local function _getNodeConfig(nodeId)
    local nodes = MockData._RUNTIME_CONFIG.nodeMetas or MockData._RUNTIME_CONFIG.nodes or {}
    local node = nodes[nodeId] or nodes[tostring(nodeId)]
    if node and node.id ~= nil and node.id ~= nodeId then node = nil end
    if node then return node end
    for _, v in ipairs(nodes) do
        if v and v.id == nodeId then return v end
    end
    return nil
end

