local _mockEnergy = nil


function MockData.getStageRewardsByProgressId(progressId)
    if not progressId or progressId <= 0 then return {} end
    for _, meta in ipairs(MockData._RUNTIME_CONFIG.stageRewardMetas or {}) do
        if progressId == meta.lastProgressId then
            return meta.rewards or {}
        end
    end
    return {}
end

function MockData.operateNode(req)
    req = req or {}
    local nodeId  = req.nodeId or 0
    local segIdx  = req.segmentIndex or 1

    local nodeCfg = _getNodeConfig(nodeId) or {}
    local segCosts = nodeCfg.energyCostPerSegments or {}
    local thisCost = segCosts[segIdx] or 0
    local totalSegs = #segCosts > 0 and #segCosts or 1
    local done = segIdx >= totalSegs

    if _mockEnergy == nil then
        _mockEnergy = MockData.mainInfo().userBean.energy
    end
    if _mockBag == nil then
        _mockBag = table.clone(MockData.mainInfo().userBean.bag or {})
    end
    _mockEnergy = math.max(0, _mockEnergy - thisCost)

    local updatedBag = {}
    if done then
        for _, reward in ipairs(nodeCfg.extraRewards or {}) do
            local itemId = reward.itemId
            if itemId ~= nil then
                local num = reward.num or reward.count or 1
                local oldCount = _mockBag[itemId] or _mockBag[tostring(itemId)] or 0
                local newCount = oldCount + num
                _mockBag[itemId] = newCount
                _mockBag[tostring(itemId)] = nil
                updatedBag[itemId] = newCount
            end
        end
    end

    return {
        energy                              = _mockEnergy,
        done                                = done,
        finishedSegments                    = segIdx,
        updatedBag                          = updatedBag,
        rewards                             = done and (nodeCfg.extraRewards or {}) or {},
        stageRewards                        = done and MockData.getStageRewardsByProgressId(nodeCfg.progressId or 0) or {},
        battlePassValue                     = done and (_mockBattlePassValue + 1) or _mockBattlePassValue,
        maxProgressId                       = done and (nodeCfg.progressId or nodeId) or 0,
        updatedTaskDataMap                  = {},
    }, 0
end

