function MockData.claimBattlePassReward(req)
    req = req or {}
    local id  = req.id or 1
    local vip = req.vip == true
    local meta = _getBattlePassMeta(id) or {}
    local rewards = vip and (meta.vipRewards or {}) or (meta.freeRewards or {})
    if vip then
        if not _contains(_mockBattlePassVipGotIds, id) then
            _mockBattlePassVipGotIds[#_mockBattlePassVipGotIds + 1] = id
        end
    else
        if not _contains(_mockBattlePassFreeGotIds, id) then
            _mockBattlePassFreeGotIds[#_mockBattlePassFreeGotIds + 1] = id
        end
    end
    return {
        rewards            = rewards,
        updatedBag         = {},
        energy             = 100,
        freeAlreadyGotIds  = _copyList(_mockBattlePassFreeGotIds),
        vipAlreadyGotIds   = _copyList(_mockBattlePassVipGotIds),
    }, 0
end

